export function moveItem<T>(list: readonly T[], from: number, to: number): T[] {
  if (
    from === to ||
    from < 0 ||
    to < 0 ||
    from >= list.length ||
    to >= list.length
  ) {
    return [...list]
  }
  const next = list.slice()
  const [item] = next.splice(from, 1)
  if (item === undefined) return [...list]
  next.splice(to, 0, item)
  return next
}

export type MoveDirection = "up" | "down" | "top" | "bottom"

export function destinationIndex(
  index: number,
  count: number,
  target: MoveDirection | number,
): number {
  if (count <= 0) return 0
  if (typeof target === "number") {
    return Math.max(0, Math.min(count - 1, target))
  }
  if (target === "up") return Math.max(0, index - 1)
  if (target === "down") return Math.min(count - 1, index + 1)
  if (target === "top") return 0
  return count - 1
}

/**
 * Reorder `order` by moving `activeId` to the slot of `overId`, but only
 * among `visibleIds`. Ids that are not visible stay where they are.
 */
export function reorderVisible(
  order: readonly string[],
  visibleIds: readonly string[],
  activeId: string,
  overId: string,
): string[] {
  const from = visibleIds.indexOf(activeId)
  const to = visibleIds.indexOf(overId)
  if (from < 0 || to < 0 || from === to) return [...order]
  const nextVisible = moveItem(visibleIds, from, to)
  const slots = new Set(visibleIds)
  let cursor = 0
  return order.map((id) => {
    if (!slots.has(id)) return id
    const next = nextVisible[cursor]
    cursor += 1
    return next ?? id
  })
}

export function reorderRows<T extends { id: string; position: number }>(
  rows: readonly T[],
  ids: readonly string[],
): T[] {
  const byId = new Map(rows.map((row) => [row.id, row]))
  const seen = new Set<string>()
  const next: T[] = []
  for (const id of ids) {
    const row = byId.get(id)
    if (!row || seen.has(id)) continue
    seen.add(id)
    next.push({ ...row, position: next.length })
  }
  for (const row of rows) {
    if (seen.has(row.id)) continue
    next.push({ ...row, position: next.length })
  }
  return next
}

/** Keep the stored position when a form saves an existing row. */
export function keepPosition<T extends { position: number }>(
  current: T | undefined,
  draft: T,
): T {
  if (!current) return draft
  return { ...draft, position: current.position }
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { LayoutGroup, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type Segment = {
  value: string
  label: string
  accessory?: React.ReactNode
}

export type SegmentedControlClassNames = {
  root?: string
  track?: string
  option?: string
  selection?: string
  label?: string
}

export type SegmentedControlProps = {
  options: Segment[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  label?: string
  onOptionIntent?: (value: string) => void
  className?: string
  classNames?: SegmentedControlClassNames
}

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  onOptionIntent,
  className,
  classNames,
}: SegmentedControlProps) {
  const id = React.useId()
  const reduced = useReducedMotion()
  const track = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "")
  const selected = value ?? internal

  React.useLayoutEffect(() => {
    const node = track.current
    if (!node) return
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1)
      node.toggleAttribute("data-fade-end", rest > 1)
    }
    edges()
    node.addEventListener("scroll", edges, { passive: true })
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges)
    observer?.observe(node)
    return () => {
      node.removeEventListener("scroll", edges)
      observer?.disconnect()
    }
  }, [options.length])

  const first = React.useRef(true)
  React.useEffect(() => {
    const node = track.current
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]')
    if (!node || !button || node.scrollWidth <= node.clientWidth) {
      first.current = false
      return
    }
    const room = 20
    const start = button.offsetLeft - room
    const end = button.offsetLeft + button.offsetWidth + room - node.clientWidth
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" })
    first.current = false
  }, [selected, reduced])

  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === selected))

  function change(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const last = options.length - 1
    const target =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? selectedIndex === last
          ? 0
          : selectedIndex + 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? selectedIndex === 0
            ? last
            : selectedIndex - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (target < 0 || !options[target]) return
    event.preventDefault()
    change(options[target].value)
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true })
  }

  return (
    <div
      data-slot="segmented-control"
      className={cn("inline-flex min-w-0 max-w-full shrink", className, classNames?.root)}
      role="group"
      aria-label={label}
    >
      <LayoutGroup id={id}>
        <motion.div
          ref={track}
          layoutScroll
          data-slot="segmented-control-track"
          className={cn(
            "flex min-w-0 gap-0.5 overflow-x-auto rounded-lg bg-muted p-0.5 [scrollbar-width:none]",
            classNames?.track,
          )}
        >
          {options.map((option, index) => {
            const pressed = selected === option.value
            return (
              <button
                key={option.value}
                id={`${id}-${option.value}`}
                type="button"
                data-slot="segmented-control-option"
                data-value={option.value}
                className={cn(
                  "relative min-h-8 shrink-0 cursor-pointer rounded-md border-0 bg-transparent px-3 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none aria-pressed:text-foreground",
                  classNames?.option,
                )}
                aria-pressed={pressed}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => change(option.value)}
                onKeyDown={onKeyDown}
                onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
                onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
              >
                {pressed ? (
                  <motion.span
                    data-slot="segmented-control-selection"
                    className={cn("absolute inset-0 z-0 rounded-md border border-border bg-background shadow-sm", classNames?.selection)}
                    layoutId="selection"
                    layoutDependency={selected}
                    transition={reduced ? { duration: 0 } : motionPresets.spring.morph}
                    aria-hidden="true"
                  />
                ) : null}
                <span data-slot="segmented-control-label" className={cn("relative z-10 inline-flex items-center gap-1.5", classNames?.label)}>
                  {option.label}
                  {option.accessory}
                </span>
              </button>
            )
          })}
        </motion.div>
      </LayoutGroup>
    </div>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import { AnimatePresence, animate, motion, useReducedMotion, type AnimationPlaybackControls } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type TextMorphProps = {
  children: string
  as?: "span" | "div" | "p" | "strong" | "h1" | "h2" | "h3"
  className?: string
  id?: string
}

const enter = [...motionPresets.ease.enter] as [number, number, number, number]
const standard = [...motionPresets.ease.standard] as [number, number, number, number]
const blurred = `blur(${motionPresets.blur.soft}px)`
const HANDOFF = 0.05

function toGlyphs(text: string) {
  const seen = new Map<string, number>()
  return Array.from(text).map((char) => {
    const count = seen.get(char) ?? 0
    seen.set(char, count + 1)
    return { char, key: `${char}-${count}` }
  })
}

const measure = (element: HTMLElement) => parseFloat(getComputedStyle(element).width)

export function TextMorph({ children, as = "span", className, id }: TextMorphProps) {
  const Tag = as
  const reduced = useReducedMotion()
  const frame = useRef<HTMLSpanElement>(null)
  const track = useRef<HTMLSpanElement>(null)
  const width = useRef(0)
  const sizing = useRef<AnimationPlaybackControls | null>(null)
  const glyphs = useMemo(() => toGlyphs(children), [children])
  const [labels, setLabels] = useState({ current: children, previous: children })
  if (labels.current !== children) setLabels({ current: children, previous: labels.current })
  const kept = useMemo(() => new Set(toGlyphs(labels.previous).map((glyph) => glyph.key)), [labels.previous])
  let entering = 0

  useLayoutEffect(() => {
    const frameElement = frame.current
    const trackElement = track.current
    if (!frameElement || !trackElement) return
    const next = measure(trackElement)
    if (!Number.isFinite(next)) return
    if (width.current && Math.abs(next - width.current) > 0.5 && !reduced) {
      sizing.current = animate(frameElement, { width: next }, motionPresets.spring.morph)
    } else {
      sizing.current?.stop()
      frameElement.style.width = `${next}px`
    }
    width.current = next
  }, [children, reduced])

  useEffect(() => {
    const frameElement = frame.current
    const trackElement = track.current
    if (!frameElement || !trackElement || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => {
      const next = measure(trackElement)
      if (!Number.isFinite(next) || Math.abs(next - width.current) < 0.5) return
      sizing.current?.stop()
      frameElement.style.width = `${next}px`
      width.current = next
    })
    observer.observe(trackElement)
    return () => observer.disconnect()
  }, [])

  return (
    <Tag id={id} data-slot="text-morph" className={cn("inline-block max-w-full", className)}>
      <span className="sr-only">{children}</span>
      <span ref={frame} className="inline-block overflow-hidden align-bottom whitespace-nowrap" aria-hidden="true">
        <span ref={track} className="inline-flex">
          <AnimatePresence mode="popLayout" initial={false}>
            {glyphs.map(({ char, key }) => {
              const order = kept.has(key) ? 0 : entering++
              return (
                <motion.span
                  key={key}
                  layout="position"
                  className="inline-block"
                  initial={reduced ? false : { opacity: 0, scale: 0.8, y: "0.14em", filter: blurred }}
                  animate={{ opacity: 1, scale: 1, y: "0em", filter: "blur(0px)" }}
                  exit={
                    reduced
                      ? { opacity: 0, transition: { duration: 0 } }
                      : { opacity: 0, scale: 0.86, y: "-0.1em", filter: blurred, transition: { duration: motionPresets.duration.exit, ease: standard } }
                  }
                  transition={
                    reduced
                      ? { duration: 0 }
                      : {
                          layout: motionPresets.spring.morph,
                          default: {
                            duration: motionPresets.duration.standard + 0.04,
                            ease: enter,
                            delay: HANDOFF + Math.min(order, 8) * motionPresets.stagger.char * 2,
                          },
                        }
                  }
                >
                  {char === " " ? "\u00a0" : char}
                </motion.span>
              )
            })}
          </AnimatePresence>
        </span>
      </span>
    </Tag>
  )
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    exit: [0.7, 0, 0.84, 0] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
